/** The map a campaign draws its headquarters on: { id, view, cities, land, countries }. Europe unless the campaign says "nearEast". */
export function mapFor(campaignId) {
  const c = CAMPAIGNS[campaignId];
  if (c && c.map === "nearEast") return { id: "nearEast", view: MAP_NEAR.view, cities: MAP_NEAR.cities, land: MAP_NEAR.land, countries: MAP_NEAR.countries };
  return { id: "europe", view: MAP_VIEW, cities: MAP_CITIES, land: MAP_LAND_PATH, countries: MAP_COUNTRIES };
}
